import { useId, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { api } from '../api/client';
import { messageOf } from '../lib/errors';

/**
 * `Import CSV` dialog for REQ-1-3-1 (Issue #3 decision D-A6).
 *
 * The file is read client-side as UTF-8 text and posted as JSON to
 * `POST /api/workbooks/import`. On success the editor opens with the complete
 * imported worksheet; on failure the dialog stays open with the chosen file and
 * shows the server's exact message (`Invalid CSV file format. Import failed.`),
 * so the home page list never shows a partial record.
 */
export function ImportCsvDialog({ onClose }: { onClose: () => void }) {
  const navigate = useNavigate();
  const titleId = useId();
  const fileInputId = useId();
  const [file, setFile] = useState<File | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const confirm = async () => {
    if (!file) {
      setError('Choose a CSV file first.');
      return;
    }
    setBusy(true);
    setError(null);
    try {
      const csv = await file.text();
      const created = await api.importWorkbookCsv(file.name, csv);
      navigate(`/workbook/${encodeURIComponent(created.id)}`);
    } catch (caught) {
      setError(messageOf(caught));
      setBusy(false);
    }
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/30 p-4"
      onMouseDown={(event) => {
        if (event.target === event.currentTarget) onClose();
      }}
    >
      <div
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        className="sheet-dialog w-full max-w-md"
      >
        <h2 id={titleId} className="mb-4 text-lg font-medium text-sheet-text">
          Import CSV
        </h2>
        <label htmlFor={fileInputId} className="mb-1 block text-sm text-sheet-text">
          CSV file
        </label>
        <input
          id={fileInputId}
          type="file"
          accept=".csv,text/csv"
          onChange={(event) => {
            setFile(event.target.files?.[0] ?? null);
            setError(null);
          }}
          className="mb-4 block w-full text-sm text-sheet-text"
        />
        {error ? (
          <p role="alert" className="mb-3 text-sm text-sheet-danger">
            {error}
          </p>
        ) : null}
        <div className="flex items-center justify-end gap-2">
          <button type="button" className="sheet-button" onClick={onClose}>
            Cancel
          </button>
          <button
            type="button"
            disabled={busy}
            onClick={() => {
              void confirm();
            }}
            className="rounded bg-sheet-accent px-4 py-1.5 text-sm text-white disabled:opacity-60"
          >
            Confirm import
          </button>
        </div>
      </div>
    </div>
  );
}

import { useId, useState } from 'react';
import { api } from '../api/client';
import { WORKBOOK_NAME_EMPTY_MESSAGE } from '../lib/copy';
import { messageOf } from '../lib/errors';

export interface RenameWorkbookDialogProps {
  workbookId: string;
  currentName: string;
  onClose: () => void;
  /** Called with the persisted name and the new `updatedAt` on success. */
  onRenamed: (name: string, updatedAt: string) => void;
}

/**
 * `Rename workbook` dialog for REQ-1-2-2 (Issue #3 decision D-A2).
 *
 * An empty (trimmed) name is rejected client-side with the exact requirement
 * message and never reaches the network; the dialog stays open and the editor
 * title keeps the original name. A failed server call shows the server message
 * in the same place and stays retryable.
 */
export function RenameWorkbookDialog({
  workbookId,
  currentName,
  onClose,
  onRenamed,
}: RenameWorkbookDialogProps) {
  const titleId = useId();
  const inputId = useId();
  const [name, setName] = useState(currentName);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const save = async () => {
    const trimmed = name.trim();
    if (!trimmed) {
      setError(WORKBOOK_NAME_EMPTY_MESSAGE);
      return;
    }
    setBusy(true);
    setError(null);
    try {
      const updated = await api.renameWorkbook(workbookId, trimmed);
      onRenamed(updated.name, updated.updatedAt);
      onClose();
    } catch (caught) {
      setError(messageOf(caught));
      setBusy(false);
    }
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/30 p-4"
      onMouseDown={(event) => {
        if (event.target === event.currentTarget) onClose();
      }}
    >
      <div
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        className="sheet-dialog w-full max-w-md"
      >
        <h2 id={titleId} className="mb-4 text-lg font-medium text-sheet-text">
          Rename workbook
        </h2>
        <form
          onSubmit={(event) => {
            event.preventDefault();
            void save();
          }}
        >
          <label htmlFor={inputId} className="mb-1 block text-sm text-sheet-text">
            Workbook name
          </label>
          <input
            id={inputId}
            value={name}
            autoFocus
            onChange={(event) => {
              setName(event.target.value);
              setError(null);
            }}
            className="mb-4 w-full rounded border-1 border-sheet-border px-2 py-1.5 text-sm text-sheet-text outline-none"
          />
          {error ? (
            <p role="alert" className="mb-3 text-sm text-sheet-danger">
              {error}
            </p>
          ) : null}
          <div className="flex items-center justify-end gap-2">
            <button type="button" className="sheet-button" onClick={onClose}>
              Cancel
            </button>
            <button
              type="submit"
              disabled={busy}
              className="rounded bg-sheet-accent px-4 py-1.5 text-sm text-white disabled:opacity-60"
            >
              Save
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
